<script lang="ts">
  import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { composeEventHandlers } from '../shared/events.js'; import { contains } from '../shared/dom.js'; import { getPopoverContext } from '../popover/popover-context.svelte.js'; import { getMenuContext } from './menu-context.svelte.js';
  export interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> { children?: Snippet; ref?: HTMLDivElement | null; }
  let { children, ref = $bindable(null), onkeydown, ...rest }: Props = $props(); const popover = getPopoverContext(); const menu = getMenuContext(); let search = ''; let searchTimer: ReturnType<typeof setTimeout>;
  function attach(node: HTMLDivElement) { popover.popup = node; queueMicrotask(() => menu.focus(1)); const outside = (event: PointerEvent) => { if (!contains(node, event.target) && !contains(popover.trigger, event.target)) popover.setOpen(false, 'outside-press', event); }; document.addEventListener('pointerdown', outside, true); return () => document.removeEventListener('pointerdown', outside, true); }
  function keydown(event: KeyboardEvent) { if (event.key === 'ArrowDown') { event.preventDefault(); menu.focus(1, document.activeElement as HTMLElement); } else if (event.key === 'ArrowUp') { event.preventDefault(); menu.focus(-1, document.activeElement as HTMLElement); } else if (event.key === 'Home') { event.preventDefault(); menu.items.find((item) => !item.disabled)?.element.focus(); } else if (event.key === 'End') { event.preventDefault(); menu.items.filter((item) => !item.disabled).at(-1)?.element.focus(); } else if ((event.key === 'Enter' || event.key === ' ') && document.activeElement instanceof HTMLElement && document.activeElement.getAttribute('role')?.startsWith('menuitem')) { event.preventDefault(); document.activeElement.click(); } else if (event.key === 'Escape') { event.preventDefault(); popover.setOpen(false, 'escape-key', event); popover.trigger?.focus(); } else if (event.key.length === 1 && !event.ctrlKey && !event.metaKey) { search += event.key.toLowerCase(); clearTimeout(searchTimer); searchTimer = setTimeout(() => { search = ''; }, 500); menu.items.find((item) => !item.disabled && item.text.toLowerCase().startsWith(search))?.element.focus(); } }
</script>
{#if popover.open}<div bind:this={ref} {...rest} id={popover.popupId} role="menu" tabindex="-1" data-open="" data-side={popover.side} data-align={popover.align} onkeydown={composeEventHandlers(onkeydown, keydown)} {@attach attach}>{@render children?.()}</div>{/if}
